window.AUTH=window.AUTH||{};window.AUTH["24-5438"]={"d":"24-5438","id":"2025/24-5438","n":"Bowe v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Michael Bowe","date":"2025-04-07","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/354841/20250407132513522_Bowe%20Merits%20Brief%20FINAL.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondent United States","date":"2025-06-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/362867/20250611130453359_24-5438bsUnitedStates.pdf","side":"res","n":100},{"k":"reply","label":"Reply of petitioner Michael Bowe","date":"2025-09-22","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/375436/20250922105855721_Bowe%20Reply%20FINAL.pdf","side":"pet","n":25}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us1r04_n7ip.pdf","tr":true,"items":[{"t":"case","label":"Avery v. United States","cite":"140 S. Ct. 1080","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/1080/","sc":1,"ar":2,"by":{"0":"9","1":"41"}},{"t":"case","label":"Bowe v. United States, __ S. Ct. __","cite":"2025 WL 226843","y":2025,"court":"Jan. 17","by":{"0":"11"}},{"t":"case","label":"Bowen v. Mich. Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Brown v. United States","cite":"942 F.3d 1069","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/1069/","op":1,"by":{"0":"7"}},{"t":"case","label":"Burt v. Titlow","cite":"571 U.S. 12","y":2013,"id":"2013/12-414","sc":1,"op":1,"sum":"The Court held that the Antiterrorism and Effective Death Penalty Act requires the Court of Appeals to apply a “doubly-deferential” standard in which both the state court and the defense attorney are given the benefit of the doubt in murder cases.","sumSrc":"Oyez","by":{"0":"25–26"}},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"op":52,"ar":21,"sum":"The Court held that a federal court can recharacterize a motion as a first habeas corpus petition only if the court: (1) informs the litigant of the court's intent to recharacterize; (2) warns the litigant that this recharacterization means that any subsequent habeas corpus petition will be treated as a second petition; (3) gives the litigant an opportunity to withdraw or amend the motion.","sumSrc":"Oyez","by":{"0":"28, 36, 38, 40–41, 43, 33","2":"15, 17–18, 21–23"}},{"t":"case","label":"Chamber of Commerce of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Cheney v. U.S. Dist. Ct. for the Dist. of Columbia","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"op":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"43","1":"31, 39, 40"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"op":2,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"0":"19, 25"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"op":8,"ar":1,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"0":"10, 29, 45–46","1":"8, 19, 22, 23, 25, 40, 41"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":2,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Green v. United States","cite":"397 F.3d 101","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/397/101/","by":{"0":"20"}},{"t":"case","label":"Groff v. DeJoy","cite":"600 U.S. 447","y":2023,"id":"2022/22-174","sc":1,"sum":"Title VII requires an employer that denies a religious accommodation to show that the burden of granting an accommodation would result in substantial increased costs in relation to the conduct of its particular business.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"Gustafson v. Alloyd Co., Inc.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"op":11,"ar":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"0":"29–30","1":"33, 34"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"28, 31–32, 43–44","1":"32"}},{"t":"case","label":"Int’l Union, United Auto., Aerospace & Agr. Implement Workers of Am. v. Brock","cite":"477 U.S. 274","y":1986,"id":"1985/84-1777","sc":1,"sum":"To supplement state unemployment insurance benefits, the Trade Act of 1974 (Act) provides federally funded trade readjustment allowance (TRA) benefits to workers laid off because of competition from imports. As authorized by the Act, the Secretary of Labor (Secretary) has contracted out to state unemployment insurance agencies the job of making individual eligibility determinations for the benefits. To qualify for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"sum":"The Court held that if a state court grants a criminal defendant the right to file an out-of-time direct appeal, the statute of limitations doesn't begin until after the out-of-time appeal is final.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"6","1":"6, 11"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"op":6,"ar":2,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 17–19, 21, 30, 46","1":"1, 3, 7, 8, 14, 22, 25, 42, 49","2":"9, 11"}},{"t":"case","label":"Jones v. United States","cite":"36 F.4th 974","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/974/","op":1,"by":{"0":"22"}},{"t":"case","label":"Lamie v. U.S. Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"op":11,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"op":3,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"0":"17","1":"36, 44, 45"}},{"t":"case","label":"Martinez-Villareal v. Stewart","cite":"118 F.3d 628","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/628/","by":{"0":"37"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Defense","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"0":"19","2":"4"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"Neil v. Biggers","cite":"409 U.S. 188","y":1972,"id":"1972/71-586","sc":1,"sum":"No. In a 5-3 decision Justice Lewis F. Powell wrote the majority opinion reversing in part and remanding. The entire court joined in the first part of the opinion, holding that affirming by an equally divided court did not constitute an “actual adjudication” of the issue. The habeas corpus proceeding could continue.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"ar":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"27, 36, 46"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"sum":"Title 8 U. S. C. §1252(d)(1)—which requires noncitizens to “exhaus[t] all administrative remedies . . . as of right” before challenging a Board of Immigration Appeals final order of removal in federal court—is not a jurisdictional provision and does not require noncitizens to request discretionary forms of review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"Shinn v. Ramirez","cite":"596 U.S. 366","y":2022,"id":"2021/20-1009","sc":1,"sum":"Under 28 U. S. C. §2254(e)(2), a federal habeas court may not conduct an evidentiary hearing or otherwise consider evidence beyond the state-court record based on the ineffective assistance of state postconviction counsel.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Shoop v. Twyford","cite":"596 U.S. 811","y":2022,"id":"2021/21-511","sc":1,"sum":"A transportation order that allows a prisoner to search for new evidence—in this case an order compelling the State to transport Mr. Twyford to a medical facility for neurological testing—is not “necessary or appropriate in aid of” a federal court’s adjudication of a habeas corpus action when the prisoner has not shown that the desired evidence would be admissible in connection with a particular claim for relief.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25–26"}},{"t":"case","label":"Stewart v. Martinez-Villareal","cite":"523 U.S. 637","y":1998,"id":"1997/97-300","sc":1,"op":2,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled Martinez-Villareal cannot be barred from raising his incompetency claim in a successive petition because his claim was really amended.","sumSrc":"Oyez","by":{"0":"37–38, 40–41","1":"37, 38","2":"17–18, 20, 22"}},{"t":"case","label":"Taylor v. Gilkey","cite":"314 F.3d 832","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/314/832/","by":{"0":"20"}},{"t":"case","label":"Thompson v. Calderon","cite":"151 F.3d 918","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/918/","by":{"0":"34"}},{"t":"case","label":"Triestman v. United States","cite":"124 F.3d 361","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/361/","sum":"Explaining that “it is logical to assume that Congress intended to refer to all of the [relevant] subsections of [Section] 2244,” “including * * * [Section] 2244(b)(3)(E)”.","sumSrc":"brief:1","by":{"0":"34","1":"25, 27"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"op":2,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7–8, 10–11, 43","1":"6, 12, 41","2":"12–14, 16"}},{"t":"case","label":"United States v. Seale","cite":"558 U.S. 985","y":2009,"url":"https://supreme.justia.com/cases/federal/us/558/985/","sc":1,"by":{"0":"47"}},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"op":1,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7–8, 27","1":"6, 13, 42","2":"12–14"}},{"t":"case","label":"United States, ex rel. Polanksy v. Exec. Health Res., Inc.","cite":"599 U.S. 419","y":2023,"id":"2022/21-1052","sc":1,"op":4,"sum":"In a qui tam action filed under the False Claims Act, the United States may move to dismiss under 31 U. S. C. §3730(c)(2)(A) whenever it has intervened—whether during the seal period or later on; in assessing a motion to dismiss an FCA action over a relator’s objection, district courts should apply the rule generally governing voluntary dismissal of suits in ordinary civil litigation—Federal Rule of Civil Procedure 41(a).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","2":"9"}},{"t":"case","label":"Utah v. Evans","cite":"536 U.S. 452","y":2002,"id":"2001/01-714","sc":1,"op":3,"ar":8,"sum":"The Court held that the use of hot-deck imputation violates neither the statute nor the Constitution.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Will v. United States","cite":"389 U.S. 90","y":1967,"id":"1967/36","sc":1,"sum":"The record in this case discloses no proper justification for the Court of Appeals to have invoked the extraordinary writ of mandamus to review the trial court's interlocutory order.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Williams v. United States","cite":"927 F.3d 427","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/427/","op":1,"by":{"0":"20"}},{"t":"case","label":"Wisniewski v. United States","cite":"353 U.S. 901","y":1957,"url":"https://supreme.justia.com/cases/federal/us/353/901/","sc":1,"op":1,"by":{"0":"47","1":"32"}},{"t":"case","label":"Woods v. Donald","cite":"575 U.S. 312","y":2015,"id":"2014/14-618","sc":1,"sum":"The Court held that federal habeas relief may only be granted when a state court’s decision runs counter to clearly established federal law, and there is no precedent clearly establishing that the absence of counsel during testimony about codefendants violates a defendant’s Sixth Amendment right to effective assistance of counsel.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"const","label":"Article I, Section 8, Clause 9","text":"To constitute Tribunals inferior to the supreme Court;","by":{"0":"45"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"45"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(e)","(e)(2)(B)(ii)","(c)(2006)","(c)(3)(A)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"6–7","1":"11, 12, 6, 11, 20, 6, 11, 12, 20, 42, 12, 13, 42, 12, 41","2":"13"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)","(2)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"41"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"2","1":"1"}},{"t":"case","label":"Abbott v. Perez","cite":"585 U.S. 579","y":2018,"id":"2017/17-586","sc":1,"op":2,"ar":1,"sum":"The Court decided that the district court erred in disregarding the presumption of good faith on the part of the Texas Legislature and improperly reversed the burden of proof in requiring the state to show a lack of discriminatory intent in adopting new districting plans; the Court also held that one of the state house districts at issue was an impermissible racial gerrymander.","sumSrc":"Oyez","by":{"1":"36","2":"19"}},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"sum":"The Court found that using a telephone to make a misdemeanor drug purchase does not facilitate the felony of drug distribution.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Artuz v. Bennett","cite":"531 U.S. 4","y":2000,"id":"2000/99-1238","sc":1,"sum":"The Court held that an application for state postconviction relief containing procedurally barred claims is properly filed within the meaning of the Antiterrorism and Effective Death Penalty Act of 1996.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Banister v. Davis","cite":"590 U.S. 504","y":2020,"id":"2019/18-6943","sc":1,"op":1,"sum":"Concluding that AEDPA did not displace the historical practice of applying Federal Rule of Civil Procedure 59(e) in habeas.","sumSrc":"opinion","by":{"1":"49"}},{"t":"case","label":"Bennett v. United States","cite":"119 F.3d 468","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/119/468/","by":{"1":"37"}},{"t":"case","label":"Bessent v. Dellinger","cite":"145 S. Ct. 1326","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/1326/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Blackledge v. Allison","cite":"431 U.S. 63","y":1977,"id":"1976/75-1693","sc":1,"sum":"In light of the nature of the record of the proceeding at which the guilty plea was accepted, and of the ambiguous status of the process of plea bargaining at the time the guilty plea was made, respondent's petition for a writ of habeas corpus should not have been summarily dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Bondi v. VanDerStok","cite":"145 S. Ct. 857","y":2025,"id":"2024/23-852","sc":1,"sum":"ATF's 2022 Rule interpreting the Gun Control Act of 1968 to cover certain products that can readily be converted into an operational firearm or a functional frame or receiver, see 27 CFR §§478.11, 478.12(c), is not facially inconsistent with the Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39"}},{"t":"case","label":"Burton v. Stewart","cite":"549 U.S. 147","y":2007,"id":"2006/05-9222","sc":1,"op":2,"sum":"In a 9-0 per curiam opinion, the Court ruled that Burton's habeas petition should be dismissed for lack of jurisdiction. Burton had earlier filed a habeas petition challenging his conviction. Four years later, when he filed the habeas petition challenging only his sentence, Burton neglected to obtain the court authorization necessary for a \"second or successive\" petition.","sumSrc":"Oyez","by":{"1":"25, 32"}},{"t":"case","label":"Cooper v. Woodford","cite":"358 F.3d 1117","y":2004,"url":"https://www.courtlistener.com/c/F.3d/358/1117/","by":{"1":"29"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Dawkins v. United States","cite":"829 F.3d 549","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/549/","by":{"1":"37"}},{"t":"case","label":"Duncan v. Bonta","cite":"131 F.4th 1019","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/131/1019/","by":{"1":"29"}},{"t":"case","label":"Gallagher v. United States","cite":"711 F.3d 315","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/711/315/","op":1,"by":{"1":"37"}},{"t":"case","label":"Gonzalez v. Automatic Emps. Credit Union","cite":"419 U.S. 90","y":1974,"id":"1974/73-858","sc":1,"sum":"When a three-judge district court denies a plaintiff injunctive relief on grounds that, if sound, would have justified dissolution of the court as to that plaintiff or a refusal to convene a three-judge court to begin with, review of the denial is available in the court of appeals; and since here the three-judge District Court's decision that the complaint was nonjusticiable for lack of \"standing\" was a ground upon …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 35, 36, 38","2":"19"}},{"t":"case","label":"Ikome v. Bondi","cite":"2025 WL 1573183","y":2025,"court":"June 4","by":{"1":"35"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"op":3,"sum":"The Court rejected the argument that the trial itself was the \"transaction\" or \"occurrence\" under federal habeas law. The Court said that such a definition would have allowed virtually any new claim introduced in an amended petition to relate back, gutting the one-year time limit on petitions.","sumSrc":"Oyez","by":{"1":"1, 8","2":"6"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"op":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40, 48","2":"11"}},{"t":"case","label":"Melendez v. United States","cite":"518 U.S. 120","y":1996,"id":"1995/95-5661","sc":1,"op":5,"sum":"The Court held that, in the absence of a Government motion requesting or authorizing the district court to \"impose a sentence below a level established by statute as minimum sentence,\" a prison sentence must not violate the statutory sentencing minimum.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Págan-San Miguel v. United States","cite":"736 F.3d 44","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/736/44/","op":1,"by":{"1":"25"}},{"t":"case","label":"Rhines v. Weber","cite":"544 U.S. 269","y":2005,"id":"2004/03-9046","sc":1,"op":1,"sum":"The Court held that a district court could stay a mixed petition to allow a petitioner to present unexhausted claims in state court and then return to federal court.","sumSrc":"Oyez","by":{"1":"29, 30"}},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"sum":"1. Warrants of removal issued in triplicate are in legal effect but a single warrant, and defendant who had secured a supersedeas on appeal from an order refusing relief by habeas corpus from arrest under one, could not lawfully be arrested under another.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"sum":"The Court should have granted a hearing on the second motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48, 49","2":"14"}},{"t":"case","label":"Summerlin v. Stewart","cite":"309 F.3d 1193","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/1193/","by":{"1":"29"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"sum":"A federal prisoner's allegation that a postsentencing change in the policies of the United States Parole Commission has prolonged his actual imprisonment beyond the period intended by the sentencing judge will not support a collateral attack on the original sentence under 28 U. S. C. § 2255.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"United States v. Campbell","cite":"26 F.4th 860","y":2022,"url":"https://www.courtlistener.com/c/F.4th/26/860/","by":{"1":"29"}},{"t":"case","label":"United States v. Handy","cite":"646 Fed. Appx. 635","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./646/635/","by":{"1":"37"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"sum":"The District Court erred in determining the factual issues raised by respondent's motion under § 2255 without notice to respondent and without his presence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"United States v. Lorentsen","cite":"106 F.3d 278","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/106/278/","by":{"1":"25"}},{"t":"case","label":"United States v. St. Hubert","cite":"909 F.3d 335","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/335/","by":{"1":"13"}},{"t":"case","label":"Welch v. United States","cite":"578 U.S. 120","y":2016,"id":"2015/15-6418","sc":1,"ar":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"White v. United States","cite":"371 F.3d 900","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/900/","by":{"1":"37"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"op":1,"sum":"The Court held that under federal law, as amended by the AEDPA, \"a 'failure to develop' a claim's factual basis in state court proceedings is not established unless there is lack of diligence, or some greater fault, attributable to the prisoner or his counsel.\" Justice Kennedy wrote for the Court that \"comity is not served by saying a prisoner 'has failed to develop the factual basis of a claim' where he was unable to develop his claim in state court despite diligent effort.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"sum":"The Court held, for purposes of Lindh, that a case does not become \"pending\" until an actual application for habeas corpus relief is filed in federal court.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"const","label":"Article III, Section 2, Clause 2","clauses":[["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make.","by":{"1":"19, 39-41"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)"],"stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1951. Interference with commerce by threats or violence","tname":"Crimes and Criminal Procedure","by":{"1":"6, 11, 6, 11"}},{"t":"usc","label":"28 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/28/46","subs":["(c)"],"by":{"1":"28"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","stext":{"head":"§1253. Direct appeals from decisions of three-judge courts","paras":[[0,"Except as otherwise provided by law, any party may appeal to the Supreme Court from an order granting or denying, after notice and hearing, an interlocutory or permanent injunction in any civil action, suit or proceeding required by any Act of Congress to be heard and determined by a district court of three judges."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1253?type=usc&year=mostrecent&link-type=html"},"head":"§1253. Direct appeals from decisions of three-judge courts","tname":"Judiciary and Judicial Procedure","by":{"1":"35, 36","2":"18–19"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2241. Power to grant writ","tname":"Judiciary and Judicial Procedure","by":{"1":"9"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(B)","(b)(2)(B)(ii)","(b)(3)","(b)(3)(A)","(b)(3)(B)","(b)(3)(C)","(b)(3)(D)","(b)(3)(E)","(b)(4)","(c)","(d)","(d)(1)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"op":51,"ar":6,"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"1":"9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(a)","(b)(1)","(b)(2)","(b)(3)","(c)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":20,"ar":8,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"1":"9, 9, 9, 9, 9, 9"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(e)","(h)","(h)(1)","(h)(2)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"op":39,"ar":2,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"1":"28, 28, 28, 28, 28, 28, 28, 28"}},{"t":"rule","label":"Fed. R. App. P. 40","url":"https://www.law.cornell.edu/rules/frap/rule_40","subs":["(d)(1)"],"by":{"1":"28"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"sum":"Administrative deportation proceedings are not adversary adjudications \"under section 554\" and thus do not fall within the category of proceedings for which the EAJA has waived sovereign immunity and authorized the award of attorney's fees and costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"sum":"The Court held that Davis could challenge his conviction under 28 U.S.C. Section 2255.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Holmes Group, Inc. v. Vornado Air Circulation Sys., Inc.","cite":"535 U.S. 826","y":2002,"id":"2001/01-408","sc":1,"sum":"The Court held that the appellate could not assert jurisdiction over such a case.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"op":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"8"}},{"t":"case","label":"SAS Institute Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"op":1,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"United States ex rel. Schutte v. SuperValu Inc.","cite":"598 U.S. 739","y":2023,"id":"2022/21-1326","sc":1,"sum":"The False Claims Act’s scienter element—which asks whether a defendant “knowingly” submitted a “false” claim to the Government, 31 U. S. C. §3729(a)—refers to a defendant’s knowledge and subjective beliefs—not to what an objectively reasonable person may have known or believed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"United States v. Miller","cite":"145 S. Ct. 839","y":2025,"id":"2024/23-824","sc":1,"sum":"Section 106(a) of the Bankruptcy Code abrogates the Government’s sovereign immunity with respect to a §544(b) claim but that waiver does not extend to state-law claims nested within that federal claim.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}}]};